import "./styles/Home.css";
import Footer from "./Footer";

const Home = () => {
  return (
    <div className="home-container">
      {/* Header section */}
      <header className="home-header">
        <h1 className="home-title">UTAS Link</h1>
        <p className="home-subtitle">
          Connecting UTAS students with local companies for part-time and
          training opportunities.
        </p>
      </header>

      {/* Search section */}
      <section className="home-search">
        <input
          type="text"
          placeholder="Search by skill, company, or job title..."
          className="search-input"
        />
        <button className="search-btn">Find Work</button>
      </section>

      {/* Categories */}
      <section className="home-categories">
        <h3>Explore Categories</h3>
        <div className="categories-grid">
          <div className="category-card">Part-Time</div>
          <div className="category-card">Hourly</div>
          <div className="category-card">Training</div>
        </div>
      </section>

      {/* Call-to-Action */}
      <section className="home-cta">
        <h3>Get Started</h3>
        <div className="cta-buttons">
          <button className="btn student">Student Login</button>
          <button className="btn company">Company Login</button>
          <button className="btn register">Register</button>
        </div>
      </section>

      {/* Footer */}
      <Footer />
    </div>
  );
};

export default Home;
